 "content": "from collections import Counter


def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Uniform full-width/full-height rails partition the grid into equal panels.
    row_rails = [r for r, row in enumerate(g) if len(set(row)) == 1]
    col_rails = [c for c in range(w) if len({g[r][c] for r in range(h)}) == 1]
    row_ranges = []
    start = 0
    for r in row_rails + [h]:
        if start < r:
            row_ranges.append((start, r))
        start = r + 1
    col_ranges = []
    start = 0
    for c in col_rails + [w]:
        if start < c:
            col_ranges.append((start, c))
        start = c + 1

    # The stencil is the occupied non-leftmost panel with the greatest
    # number of non-background cells; its exact nonzero footprint is copied.
    candidates = []
    for ri, (r0, r1) in enumerate(row_ranges):
        for ci, (c0, c1) in enumerate(col_ranges):
            if ci == 0:
                continue
            cells = [(r-r0, c-c0) for r in range(r0, r1) for c in range(c0, c1) if g[r][c] != 0]
            if cells:
                candidates.append((len(cells), ri, ci, cells))
    if not candidates:
        return g
    _, _, _, footprint = max(candidates)

    # Each panel row's leftmost block supplies the color used for that row.
    for ri, (r0, r1) in enumerate(row_ranges):
        c0, c1 = col_ranges[0]
        counts = Counter(g[r][c] for r in range(r0, r1) for c in range(c0, c1) if g[r][c] != 0)
        if not counts:
            continue
        color = counts.most_common(1)[0][0]
        for b0, b1 in col_ranges:
            for dr, dc in footprint:
                rr, cc = r0 + dr, b0 + dc
                if rr < r1 and cc < b1:
                    g[rr][cc] = color
    return g


if __name__ == '__main__':
    pass
